package com.example.demo.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import jakarta.validation.Valid;

import java.time.LocalDate;
import java.time.Period;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "patients")
public class Patient {

    /** Internal primary key, generated by the system. */
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    /** Human-readable record ID (e.g. PT-2026-3F9A1C2B), generated by the system. */
    @Column(name = "patient_number", nullable = false, unique = true, updatable = false, length = 30)
    private String patientNumber;

    @NotBlank
    @Size(max = 150)
    @Column(name = "full_name", nullable = false, length = 150)
    private String fullName;

    @Size(max = 150)
    @Column(name = "previous_name", length = 150, nullable = true)
    private String previousName;

    @NotNull
    @Past
    @Column(name = "date_of_birth", nullable = false)
    private LocalDate dateOfBirth;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Sex sex;

    @Size(max = 80)
    private String nationality;

    @Size(max = 80)
    @Column(name = "state_of_origin", length = 80)
    private String stateOfOrigin;

    @Enumerated(EnumType.STRING)
    @Column(name = "marital_status", length = 20)
    private MaritalStatus maritalStatus;

    @Size(max = 100)
    private String occupation;

    @Enumerated(EnumType.STRING)
    @Column(name = "education_level", length = 20)
    private EducationLevel educationLevel;

    @Size(max = 300)
    @Column(name = "residential_address", length = 300)
    private String residentialAddress;

    @NotBlank
    @Pattern(regexp = "^\\+?[0-9 ()-]{7,20}$", message = "Invalid phone number")
    @Column(name = "phone_number", nullable = false, length = 20)
    private String phoneNumber;

    @Email
    @Size(max = 150)
    @Column(name = "email_address", length = 150)
    private String emailAddress;

    @Size(max = 50)
    @Column(name = "preferred_language", length = 50)
    private String preferredLanguage;

    @Enumerated(EnumType.STRING)
    @Column(name = "preferred_communication_method", length = 20)
    private CommunicationMethod preferredCommunicationMethod;

    @Valid
    @OneToMany(mappedBy = "patient", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<NextOfKin> nextOfKin = new ArrayList<>();

    @PrePersist
    void generatePatientNumber() {
        if (patientNumber == null) {
            String suffix = UUID.randomUUID().toString().replace("-", "").substring(0, 8).toUpperCase();
            patientNumber = "PT-" + LocalDate.now().getYear() + "-" + suffix;
        }
    }

    /** Calculated automatically from date of birth; never stored. */
    @Transient
    public Integer getAge() {
        return dateOfBirth == null ? null : Period.between(dateOfBirth, LocalDate.now()).getYears();
    }

    public void addNextOfKin(NextOfKin kin) {
        nextOfKin.add(kin);
        kin.setPatient(this);
    }

    public void removeNextOfKin(NextOfKin kin) {
        nextOfKin.remove(kin);
        kin.setPatient(null);
    }

    public UUID getId() { return id; }
    public String getPatientNumber() { return patientNumber; }

    public String getFullName() { return fullName; }
    public void setFullName(String fullName) { this.fullName = fullName; }

    public String getPreviousName() { return previousName; }
    public void setPreviousName(String previousName) { this.previousName = previousName; }

    public LocalDate getDateOfBirth() { return dateOfBirth; }
    public void setDateOfBirth(LocalDate dateOfBirth) { this.dateOfBirth = dateOfBirth; }

    public Sex getSex() { return sex; }
    public void setSex(Sex sex) { this.sex = sex; }

    public String getNationality() { return nationality; }
    public void setNationality(String nationality) { this.nationality = nationality; }

    public String getStateOfOrigin() { return stateOfOrigin; }
    public void setStateOfOrigin(String stateOfOrigin) { this.stateOfOrigin = stateOfOrigin; }

    public MaritalStatus getMaritalStatus() { return maritalStatus; }
    public void setMaritalStatus(MaritalStatus maritalStatus) { this.maritalStatus = maritalStatus; }

    public String getOccupation() { return occupation; }
    public void setOccupation(String occupation) { this.occupation = occupation; }

    public EducationLevel getEducationLevel() { return educationLevel; }
    public void setEducationLevel(EducationLevel educationLevel) { this.educationLevel = educationLevel; }

    public String getResidentialAddress() { return residentialAddress; }
    public void setResidentialAddress(String residentialAddress) { this.residentialAddress = residentialAddress; }

    public String getPhoneNumber() { return phoneNumber; }
    public void setPhoneNumber(String phoneNumber) { this.phoneNumber = phoneNumber; }

    public String getEmailAddress() { return emailAddress; }
    public void setEmailAddress(String emailAddress) { this.emailAddress = emailAddress; }

    public String getPreferredLanguage() { return preferredLanguage; }
    public void setPreferredLanguage(String preferredLanguage) { this.preferredLanguage = preferredLanguage; }

    public CommunicationMethod getPreferredCommunicationMethod() { return preferredCommunicationMethod; }
    public void setPreferredCommunicationMethod(CommunicationMethod m) { this.preferredCommunicationMethod = m; }

    public List<NextOfKin> getNextOfKin() { return nextOfKin; }
}